item.aggregated_output:
      wait.clear();
      if (customer.phase === 'waiting-stock') {
        wait.lineStyle(4, 0xf28f6b, 1).beginPath().arc(0, 0, 28, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * (customer.waitingMs / 8_000)).strokePath();
      }
    }
  }

  private syncTokens() {
    const active = new Set(state.tokens.map((token) => token.id));
    for (const [id, view] of this.tokenViews) {
      if (!active.has(id)) { view.destroy(true); this.tokenViews.delete(id); }
    }
    for (const token of state.tokens) {
      let view = this.tokenViews.get(token.id);
      if (!view) {
        const shell = this.add.circle(0, 0, 15, 0xf4d58d, 1).setStrokeStyle(4, 0xf8fae5);
        const mark = this.add.text(0, -1, '◒', { fontFamily: 'system-ui', fontSize: '18px', color: '#F28F6B' }).setOrigin(0.5);
        view = this.add.container(token.position.x, token.position.y, [shell, mark]).setDepth(16);
        this.tweens.add({ targets: view, scale: 1.12, duration: 520, yoyo: true, repeat: -1, ease: 'Sine.InOut' });
        this.tokenViews.set(token.id, view);
      }
      view.setPosition(token.position.x, token.position.y - Math.sin(token.ageMs / 220) * 3);
    }
  }

  private syncProducts() {
    const signature = `${state.carried.join(',')}|${state.stock.fish}|${state.stock.kelp}|${state.unlocks.kelp}`;
    if (signature !== this.productSignature) {
      this.productSignature = signature;
      for (const view of [...this.carriedViews, ...this.shelfViews]) view.destroy();
      this.carriedViews = state.carried.map((product, index) => this.add.image(0, 0, product)
        .setDisplaySize(25, 25)
        .setDepth(22 + index));
      this.shelfViews = [];
      const addShelfStack = (product: ProductId, count: number, center: { x: number; y: number }) => {
        for (let index = 0; index < Math.min(count, 8); index += 1) {
          this.shelfViews.push(this.add.image(
            center.x - 27 + (index % 4) * 18,
            center.y + 11 - Math.floor(index / 4) * 18,
            product,
          ).setDisplaySize(22, 22).setDepth(6 + index));
        }
      };
      addShelfStack('fish', state.stock.fish, STATIONS.fishShelf);
      if (state.unlocks.kelp) addShelfStack('kelp', state.stock.kelp, STATIONS.kelpShelf);
    }
    this.carriedViews.forEach((view, index) => view.setPosition(
      state.player.position.x + (index % 2 === 0 ? -9 : 9),
      state.player.position.y - 42 - index * 13,
    ));
  }

  syncAll() {
    if (!this.player) return;
    this.player.setPosition(state.player.position.x, state.player.position.y);
    this.player.setDisplaySize(68 + (state.player.capacity - 4) * 3, 68 + (state.player.capacity - 4) * 3);
    this.kelpObjects.forEach((object) => {
      if ('setAlpha' in object) (object as Phaser.GameObjects.Image).setAlpha(state.unlocks.kelp ? 1 : 0.25);
    });
    this.constructionLabel?.setText(state.unlocks.kelp ? '✓ 开放' : `${state.construction.invested} / 12`);
    this.capacityLabel?.setText(`+${state.player.capacity - 4}`);
    this.syncProducts();
    this.syncCustomers();
    this.syncTokens();
  }
}

