describe('spatial seafood logistics', () => {
  it('harvests fish and only delivers products to a compatible shelf', () => {
    const state = createInitialState();
    state.player.position = { ...STATIONS.fishSource };

    advanceGame(state, { x: 0, y: 0 }, HARVEST_MS);
    expect(state.carried).toEqual(['fish']);

    state.carried.push('kelp');
    state.player.position = { ...STATIONS.fishShelf };
    advanceGame(state, { x: 0, y: 0 }, 1_000);

    expect(state.stock).toEqual({ fish: 1, kelp: 0 });
    expect(state.carried).toEqual(['kelp']);
  });

  it('unlocks kelp through construction and enables its full supply route', () => {
    const state = createInitialState();
    grantCurrency(state, CONSTRUCTION_COST);
    state.player.position = { ...STATIONS.construction };

    advanceGame(state, { x: 0, y: 0 }, 5_000);
    expect(state.unlocks.kelp).toBe(true);
    expect(state.construction.invested).toBe(CONSTRUCTION_COST);

    state.player.position = { ...STATIONS.kelpSource };
    advanceGame(state, { x: 0, y: 0 }, HARVEST_MS);
    state.player.position = { ...STATIONS.kelpShelf };
    advanceGame(state, { x: 0, y: 0 }, 1_000);

    expect(state.stock.kelp).toBe(1);
  });

  it('serves the checkout queue in FIFO order and creates physical shell tokens', () => {
    const state = createInitialState();
