    expect(completeQueuedOrder(state)?.customerId).toBe(first.id);
    expect(state.customers.find((customer) => customer.id === second.id)?.phase).toBe('queue');
    expect(state.tokens).toHaveLength(1);
    expect(state.currency).toBe(0);

    state.player.position = { ...state.tokens[0].position };
    advanceGame(state, { x: 0, y: 0 }, 16);
    expect(state.tokens).toHaveLength(0);
    expect(state.currency).toBe(4);
  });

  it('upgrades visible carrying capacity with the blueprint base cost', () => {
    const state = createInitialState();
    grantCurrency(state, 15);

    expect(upgradeCapacity(state)).toBe(true);
    expect(state.player.capacity).toBe(5);
    expect(state.capacityLevel).toBe(2);
    expect(state.currency).toBe(0);
  });

  it('uses only local feedback for repeating automatic interactions', () => {
    const state = createInitialState();
    state.player.position = { ...STATIONS.fishSource };

    const result = advanceGame(state, { x: 0, y: 0 }, HARVEST_MS * 3);

    expect(result.events.filter((event) => event.type === 'product-picked')).toHaveLength(3);
    expect(result.events.map((event) => event.type)).not.toContain('camera-flash');
  });
