import type { GameState } from '../game/model';

export type HudView = {
  currency: string;
  capacity: string;
  fishStock: string;
  kelpStock: string;
  objective: string;
  construction: string;
};

export function getHudView(state: GameState): HudView {
  const queueCount = state.customers.filter((customer) => customer.phase === 'queue').length;
  const waitingCount = state.customers.filter((customer) => customer.phase === 'waiting-stock').length;
  let objective = '到近岸渔网装鱼，再送往蓝色冰盘';
  if (state.tokens.length > 0) objective = '收银完成！靠近发光贝壳币拾取';
  else if (queueCount > 0) objective = `收银台有 ${queueCount} 位游客，靠近自动结账`;
  else if (waitingCount > 0) objective = '游客正在等货，快去补充对应货架';
  else if (!state.unlocks.kelp && state.currency > 0) objective = '把贝壳币投入右下角建设区，解锁海带';
  return {
    currency: String(state.currency),
    capacity: `${state.carried.length} / ${state.player.capacity}`,
    fishStock: String(state.stock.fish),
    kelpStock: state.unlocks.kelp ? String(state.stock.kelp) : '未解锁',
    objective,
    construction: state.unlocks.kelp ? '海带已开张' : `${state.construction.invested} / 12`,
  };
}
    currentScene?.syncAll();
    renderHud();
  },
});

